.btn-ghost:hover { background: rgba(108, 76, 241, 0.06); color: var(--violet-dark); }
.btn-ext {
  font-size: 0.66rem; font-weight: 700; letter-spacing: 0.05em;
  padding: 2px 6px; border-radius: 6px; margin-left: 2px;
  background: rgba(108, 76, 241, 0.12); color: var(--violet-dark);
}

.plan-result { margin-top: 24px; border-top: 1px solid var(--line); padding-top: 22px; }

/* Live controls — sit directly above the schedule they shape; every change
   re-plans instantly. Day hours + meal breaks are also draggable on the graphic. */
/* Three groups side by side, each a fieldset with its question as the legend;
   they stack into one column when the row can't hold them. "Your day" gets the
   most room because the meal breaks live there. The dividers are borders on the
   groups rather than gaps, so the box reads as one panel with sections. */
.plan-controls {
  display: grid;
  /* The first two groups take exactly what their controls need — sized to
     content, they never wrap a lone control onto a second row with empty space
     beside it — and the travel group absorbs the remainder, where its hint has
     somewhere to sit. */
  /* `auto`, not `max-content`: the first two size to their content but will
     yield when the row is tight, so the travel group always keeps enough width
     for its three buttons instead of clipping the last one. */
  grid-template-columns: auto auto minmax(244px, 1fr);
  margin-bottom: 20px;
  background: #fafaff; border: 1px solid var(--line); border-radius: 12px;
}
.ctl-group {
  min-width: 0; margin: 0; padding: 14px 18px;
  border: none; border-left: 1px solid var(--line);
}
.ctl-group:first-child { border-left: none; }
.ctl-group-title {
  padding: 0; margin-bottom: 12px;
  font-family: var(--display); font-size: 0.78rem; font-weight: 700;
  color: var(--ink);
}
.ctl-group-body { display: flex; align-items: flex-start; gap: 12px 18px; flex-wrap: wrap; }
/* Side by side, "Your day" is deliberately two rows — the clocks, then the meal
   breaks underneath — rather than letting a wrap decide. The meal row is much
   wider than the two clocks, so any width where they'd share a line makes this
   group wider than the other two can spare. Stacked (below), the group has the
   full width and they sit happily on one line, so this only applies up here. */
@media (min-width: 1081px) {
  .ctl-group--day .ctl-group-body { display: grid; grid-template-columns: auto auto 1fr; }
  .ctl-group--day .ctl-meals { grid-column: 1 / -1; }
}
/* Below this the three groups can't sit side by side without the content-sized
   columns overflowing, so they stack. */
@media (max-width: 1080px) {
  .plan-controls { grid-template-columns: 1fr; }
  .ctl-group { border-left: none; border-top: 1px solid var(--line); }
  .ctl-group:first-child { border-top: none; }
}

.ctl { display: flex; flex-direction: column; gap: 6px; min-width: 84px; }
.ctl-label {
  text-transform: uppercase; letter-spacing: 0.05em;
  font-size: 0.68rem; font-weight: 700; color: var(--muted);
}
.ctl-hint { font-size: 0.7rem; color: #98a2b3; max-width: 220px; line-height: 1.35; margin: 2px 0 0; }
/* Time + number inputs, matched to the .opt-select chrome. One height across
   every control in the box — the mismatched ones were most of why it looked
   thrown together. */
.ctl-time, .ctl-num {
  font: inherit; font-size: 0.86rem; font-weight: 600; color: var(--ink);
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
  padding: 0 9px; height: 34px;
}
.ctl-num { width: 68px; }
/* Plain HH:MM clock text boxes (day start / day end). */
.ctl-clock { width: 76px; text-align: center; font-variant-numeric: tabular-nums; letter-spacing: 0.02em; }
.ctl-clock:invalid { border-color: var(--warn); }
.ctl-time:focus-visible, .ctl-num:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
/* Travel-mode segmented control. (Class name avoids the calendar's .seg.) */
.tmode { display: inline-flex; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: #fff; align-self: flex-start; height: 34px; }
.tmode-btn {
  font: inherit; font-size: 0.82rem; font-weight: 600; color: var(--muted);
  background: #fff; border: none; padding: 0 11px; cursor: pointer;
  border-right: 1px solid var(--line); white-space: nowrap;
}
.tmode-btn:last-child { border-right: none; }
.tmode-btn:hover { background: rgba(108, 76, 241, 0.05); }
.tmode-btn.is-on { background: var(--violet); color: #fff; }
/* Meal-break toggles. */
.ctl-meals { min-width: 232px; }
.meals { display: flex; flex-direction: column; gap: 6px; }
.meal { display: flex; align-items: center; gap: 6px; font-size: 0.82rem; color: var(--ink); cursor: pointer; }
.meal input[type="checkbox"] { accent-color: var(--violet); width: 15px; height: 15px; }
.meal-name { min-width: 46px; font-weight: 600; }
/* Shorter than the day-hours boxes — two of them plus a dash sit on one line,
   and matching the 34px would make the meal rows tower over their neighbours. */
.meal .meal-time { padding: 0 6px; height: 28px; font-size: 0.78rem; }
.meal-dash { color: var(--muted); }

.plan-summary { font-size: 0.92rem; color: var(--ink); margin-bottom: 14px; }
.plan-summary b { color: var(--violet-dark); font-weight: 800; }

/* --- The schedule graphic --- */
.schedule-wrap {
  overflow-x: auto; border: 1px solid var(--line); border-radius: 12px;
  background:
    linear-gradient(#fff, #fff) padding-box,
    repeating-linear-gradient(90deg, #fbfbfd 0 1px, transparent 1px 100%);
  padding: 0;
}
/* position:relative anchors the draggable day-hours / meal overlay. */
.schedule { display: flex; align-items: stretch; min-width: min-content; width: 100%; position: relative; }

