input.content:
import { chromium } from 'playwright-core';

const exe = '/opt/pw-browsers/chromium-1194/chrome-linux/chrome';
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] });
const page = await (await browser.newContext({ viewport: { width: 1400, height: 1000 } })).newPage();
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push(String(e)));

await page.goto('http://localhost:8321/plan/', { waitUntil: 'networkidle' });

// Wait for the catalogue, then seed favourites the same way the debug menu does.
await page.waitForFunction(() => !document.getElementById('loadingState') || document.getElementById('loadingState').hidden, null, { timeout: 30000 });

// Reveal + use the debug menu if present; otherwise seed via localStorage is riskier.
const seeded = await page.evaluate(() => {
  const pill = document.getElementById('debugPill');
  const btn = document.getElementById('debugRandomBtn');
  if (!pill || !btn) return 'no-debug';
  document.getElementById('debugMenu').hidden = false;
  pill.click();
  btn.click();
  return 'clicked';
});
console.log('seed:', seeded);
await page.waitForSelector('#planPanel:not([hidden])', { timeout: 20000 });
await page.waitForTimeout(800);

const ctl = page.locator('.plan-controls');
await ctl.scrollIntoViewIfNeeded();
await ctl.screenshot({ path: 'controls.png' });
const box = await ctl.boundingBox();
console.log('controls box:', box);

// Whole plan panel for context
await page.locator('#planPanel').screenshot({ path: 'panel.png' });

// Toggle dinner on to check the expanding pill
await page.click('#mealDinnerOn + .meal-pill');
await page.waitForTimeout(400);
await ctl.screenshot({ path: 'controls-dinner-on.png' });

// Narrow viewport wrap check
await page.setViewportSize({ width: 780, height: 1000 });
await page.waitForTimeout(400);
await ctl.screenshot({ path: 'controls-narrow.png' });

// 375px phone
await page.setViewportSize({ width: 375, height: 900 });
await page.waitForTimeout(400);
await ctl.screenshot({ path: 'controls-phone.png' });

console.log('console errors:', errors.length ? errors : 'none');
await browser.close();

